theorem IsPerfectoidization.comp_ringEquiv {S S' C : Type u}
    [CommRing S] [CommRing S'] [CommRing C]
    {p : ℕ} [Fact p.Prime] {f : S →+* C}
    (hf : IsPerfectoidization p f) (e : S' ≃+* S) :
    IsPerfectoidization p (f.comp e.toRingHom)

def isCoproduct (n : ℕ) :
    IsColimit (Cofan.mk ((cosimplicial E).obj ⦋n⦌) (fun i : Fin (n + 1) =>
      (cosimplicial E).map (SimplexCategory.const ⦋0⦌ ⦋n⦌ i)))

def idealBaseChangeEquiv (f : Hom P Q) :
    letI := f.toRingHom.toAlgebra
    B ⊗[A] P.ideal ≃ₗ[B] Q.ideal
